CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS owner (id INTEGER PRIMARY KEY CHECK(id=1), password_hash BLOB NOT NULL, salt BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, pin_hash BLOB, salt BLOB, attempts INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token_hash BLOB PRIMARY KEY, subject TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_items (id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL, relative_path TEXT NOT NULL, local_only INTEGER NOT NULL DEFAULT 1, root_kind TEXT NOT NULL DEFAULT 'film', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS catalog_title ON catalog_items(title COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS scan_runs (id TEXT PRIMARY KEY, started_at INTEGER NOT NULL, finished_at INTEGER, status TEXT NOT NULL, scanned INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, unmatched INTEGER NOT NULL DEFAULT 0, message TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS progress (profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, catalog_id TEXT NOT NULL REFERENCES catalog_items(id) ON DELETE CASCADE, position_ms INTEGER NOT NULL, PRIMARY KEY(profile_id, catalog_id));
